import java.util.*;import com.koios.game.arpg.*;import com.koios.game.model.item.*;import com.koios.game.model.player.Player;import com.koios.network.GamePacket;import com.koios.client.stream.Stream;
public final class CraftingPanelPagingCheck {
 static int checks;static void check(boolean b,String label){checks++;if(!b)throw new AssertionError(label);}
 static String panel(Player p){List<GamePacket> packets=((PrototypeIntegrationCheck.SessionStub)p.getSession()).packets;for(int i=packets.size()-1;i>=0;i--){GamePacket packet=packets.get(i);if(packet.getOpcode()!=126)continue;byte[] bytes=new byte[packet.getSize()];packet.getBuffer().getBytes(packet.getBuffer().readerIndex(),bytes);Stream s=new Stream(bytes);String value=s.readString();if(s.method435()==65531)return new String(Base64.getDecoder().decode(value),java.nio.charset.StandardCharsets.UTF_8);}throw new AssertionError("No panel packet");}
 static long count(String text,String prefix){return Arrays.stream(text.split("\n")).filter(line->line.startsWith(prefix)).count();}
 public static void main(String[]args)throws Exception{PrototypeIntegrationCheck.loaded();Player p=PrototypeIntegrationCheck.player("craftpaging",76);PrototypeIntegrationCheck.idle(p);p.setAttribute("tutorial-stage",11);PrototypePanel.handle(p,"arpgproto craft");check(panel(p).startsWith("craft\n")&&count(panel(p),"select ")==0,"Empty craft landing explains use without fake inventory entries");for(int slot=0;slot<13;slot++)p.getInventory().set(slot,MapRuns.gem(1,slot%2==0));p.getInventory().set(20,AffixCatalog.starter(true));p.getInventory().set(21,MapRuns.map(1,0));PrototypePanel.handle(p,"arpgproto craft");check(count(panel(p),"select ")==6&&panel(p).contains("page 1\t")&&!panel(p).contains("page -1"),"Craft landing pages six gems, excluding gear/maps");PrototypePanel.handle(p,"arpgproto page 1");check(count(panel(p),"select ")==6&&panel(p).contains("select 6\t")&&panel(p).contains("page 0\t")&&panel(p).contains("page 2\t"),"Middle page has exact six slots and both navigation actions");PrototypePanel.handle(p,"arpgproto page 999");check(count(panel(p),"select ")==1&&panel(p).contains("select 12\t")&&!panel(p).contains("Next page"),"Oversized page clamps to last nonempty page");PrototypePanel.handle(p,"arpgproto select 12");check(panel(p).contains("learn 2\t")&&panel(p).contains("items\t"),"Selected support gem offers finite ownership claims and back");PrototypePanel.handle(p,"arpgproto items");check(panel(p).contains("select 12\t")&&!panel(p).contains("learn 2\t"),"Back restores last gem page and clears selection");for(int slot=0;slot<13;slot++)p.getInventory().set(slot,null);PrototypePanel.show(p,"craft");check(p.getAttribute("prototype-page",-1)==0&&count(panel(p),"select ")==0,"Removing last-page items clamps back to empty first page");for(int slot=0;slot<8;slot++)p.getInventory().set(slot,MapRuns.map(1,0));p.getInventory().set(15,MapRuns.gem(1,false));PrototypePanel.handle(p,"arpgproto maps");check(count(panel(p),"open ")==6&&!panel(p).contains("Uncut Skill Gem"),"Maps page filters gems and respects six-slot page size");PrototypePanel.handle(p,"arpgproto page 1");check(count(panel(p),"open ")==3,"Map second page includes remaining maps only");
 Item gem=MapRuns.gem(1,true);p.getInventory().set(15,gem);PrototypePanel.handle(p,"arpgproto select 15");p.setTeleporting(true);PrototypePanel.handle(p,"arpgproto learn 2");check(p.getInventory().get(15)==gem&&p.getArpgSkills().owned(0)==0,"Teleport blocks learning without consumption or ownership");PrototypeIntegrationCheck.idle(p);PrototypePanel.handle(p,"arpgproto learn 2");check(p.getInventory().get(15)==null&&p.getArpgSkills().owned(0)==1,"Eligible selected support learns after travel completes");System.out.println("Passed "+checks+" server crafting panel paging/landing checks.");}
}
